type Props = {
  variant?: 'primary' | 'ghost' | 'danger';
  size?: 'md' | 'lg';
  style?: StyleXStyles;
  children: React.ReactNode;
};

export function Button({variant = 'primary', size = 'md', style, children}: Props) {
  return (
    <button {...stylex.props(styles.base, styles[size], styles[variant], style)}>
      {children}
    </button>
  );
}

